        $statesData = [];
        $districtsData = [];
        $localitiesData = [];

        $stateId = 1;
        $districtId = 1;
        $localityId = 1;

        foreach ($states as $code => $name) {
            $statesData[] = [
                'id' => $stateId,
                'code' => $code,
                'name' => $name
            ];

            if (isset($districts[$code])) {
                foreach ($districts[$code] as $districtName) {
                    $districtsData[] = [
                        'id' => $districtId,
                        'state_id' => $stateId,
                        'name' => $districtName
                    ];

                    $slug = str_replace(' ', '-', strtolower($districtName));
                    if (isset($localities[$slug])) {
                        foreach ($localities[$slug] as $localityName) {
                            $localitiesData[] = [
                                'id' => $localityId,
                                'district_id' => $districtId,
                                'name' => $localityName
                            ];
                            $localityId++;
                        }
                    }
                    $districtId++;
                }
            }
            $stateId++;
        }

        // Insert in bulk chunks to prevent SQL query limit errors
        foreach (array_chunk($statesData, 100) as $chunk) {
            DB::table('states')->insert($chunk);
        }
        foreach (array_chunk($districtsData, 100) as $chunk) {
            DB::table('districts')->insert($chunk);
        }
        foreach (array_chunk($localitiesData, 100) as $chunk) {
            DB::table('localities')->insert($chunk);
        }
    }
